--- Generates and executes a CMake command to configure a build system.
-- @param source    (string) The source directory containing the `CMakeLists.txt` file.
-- @param build     (string) The build directory where generated files will be placed.
-- @param install   (string) The installation directory for compiled binaries.
-- @param generator (string) The CMake generator to use (e.g., `"Ninja"`, `"Unix Makefiles"`, `"Visual Studio 17 2022"`).
-- @param options   (string|nil) Additional CMake options (optional). Defaults to an empty string if not provided.
local function cmakeGenerate(source, build, install, generator, options)
    local command = string.format(
        'cmake -S "%s" -B "%s" ' ..         -- Set CMake source and (project files) build directory
        '-D CMAKE_INSTALL_PREFIX="%s" ' ..  -- Set CMake install target directory
        '-G "%s" ' ..                       -- Choose project files generator
        ' %s ' ..                           -- Add extra options
        '-D CMAKE_RELEASE_POSTFIX="" ' ..   -- Ensure release artifacts have no postfix
        '-D CMAKE_DEBUG_POSTFIX="_d"',      -- Ensure debug artifacts have '_d' postfix, making them recognizable
        source, build, install, generator, options or ""
    )
    safeExecute(command)
end

--- Builds and installs a CMake project.
-- @param build   (string) The build directory where the CMake project has already been generated.
--                This directory contains the build system files generated by CMake (e.g., Makefiles, Visual Studio files).
-- @param config  (string) The build configuration (e.g., `"Release"`, `"Debug"`, etc.) to use during the build and install process.
local function cmakeBuild(build, config)
    local processors = getProcessorCount()
    printf([[Build and install cmake project using %d processors.]], processors)
    safeExecute(string.format('cmake --build "%s" --config %s --parallel %d', build, config, processors))
    safeExecute(string.format('cmake --install "%s" --config %s', build, config))
end

--- Generates, builds, and installs a CMake project.
-- This function automates the entire process of running CMake to generate build system files,
-- compiling the project, and installing it into a designated directory.
-- @param source    (string) The source directory containing the `CMakeLists.txt` file.
-- @param name      (string) The name of the project (used to determine the build and install directories).
-- @param config    (string) The build configuration (e.g., `"Release"`, `"Debug"`, etc.).
-- @param generator (string) The CMake generator to use (e.g., `"Ninja"`, `"Unix Makefiles"`, `"Visual Studio 17 2022"`).
-- @param options   (string|nil) Additional CMake options (optional). Defaults to an empty string if not provided.
local function cmakeGenerateAndBuild(source, name, config, generator, options)
    local build = path.join(dir.vendorBuilds, name)
    local install = path.join(dir.vendorArtifacts, name)

    touchDir(build)
    touchDir(install)

    cmakeGenerate(source, build, install, generator, options)
    cmakeBuild(build, config)
end

--- Copies vendor source files to destination directories, handling optional recursive copy and extension filtering.
-- This function processes the source directories for a specific vendor, copying them into the appropriate destination directories.
-- It validates source paths and supports recursive copying of subdirectories, as well as extension-based filtering for source files.
-- The function also generates a separate "include" directory by copying only header files and excluding source files like `.c` or `.cpp`.
-- 
-- @param name    (string) The name of the vendor whose source files are being processed.
-- @param sources (table) A table where each entry represents a source directory and associated configuration. Each entry is itself a table containing:
--                       - `source`     (string): The absolute path to the source directory.
--                       - `relPathFix` (boolean): Whether to try and preserve the subdirs relative path from the first sources entry
--                       - `recursive`  (boolean): Whether to recursively copy subdirectories from the source.
--                       - `extFilters` (table|null): A list of file extensions (e.g., `".h"`, `".cpp"`) to filter the files for copying. If `nil`, all files are copied.
-- 
-- @error Throws an error if the assumed source root directory doesn't exist or if any of the specified source directories don't exist.
local function bySource(name, sources)
    local sourceDestination = path.join(dir.vendorArtifacts, name, "source", name)
    local includeDestination = path.join(dir.vendorArtifacts, name, "include", name)
    touchDir(sourceDestination)
    touchDir(includeDestination)

    -- Assume that first path of the first entry in sources represents this vendors (source) root
    local assumedRoot = sources[1][1]
    if not os.isdir(assumedRoot) then error([[Including vendor by source failed. Assumed source root directory "%s" doesn't exist]], assumedRoot) end

    -- Copy all sources/subdirectories based on settings
    for i, entry in ipairs(sources) do
        local source = entry[1]
        local relPathFix = entry[2]
        local recursive = entry[3]
        local extFilters = entry[4]

        if not os.isdir(source) then error(string.format([[Failed copying "%s" vendor source. Directory "%s" doesn't exist.]], name, source)) end

        local finalSourceDestination = sourceDestination
        if relPathFix then
            finalSourceDestination = path.join(sourceDestination, getRelativePath(assumedRoot, source))
        end

        advancedCopy(source, finalSourceDestination, recursive, extFilters, false)
    end

    -- 'Generate' include directory from copied source by re-copying but excluding .c/.cpp files
    advancedCopy(sourceDestination, includeDestination, true, { ".c", ".cpp" }, true)
end

